<?php
use PHPUnit\Framework\TestCase;use ZinCelestial\Platform\Workflow\{ActionRegistry,WorkflowDefinition,WorkflowEngine,WorkflowRun};use ZinCelestial\Platform\Workflow\Contracts\{ActionHandlerInterface,WorkflowRepositoryInterface};
final class WorkflowIntegrationRecoveryTest extends TestCase {private function repo():WorkflowRepositoryInterface{return new class implements WorkflowRepositoryInterface{public array $runs=[];private bool $claimed=false;public function save(WorkflowRun $r,int $v):int{$this->runs[$r->id()]=$r;return$v+1;}public function get(string $id):?WorkflowRun{return$this->runs[$id]??null;}public function claim(string $id,string $w,int $s):bool{if($this->claimed)return false;$this->claimed=true;return true;}public function heartbeat(string $id,string $w,int $s):bool{return$this->claimed;}public function release(string $id,string $w):void{$this->claimed=false;}};}
 public function test_multi_step_execution_and_persistence():void{$repo=$this->repo();$reg=new ActionRegistry();$reg->register(new class implements ActionHandlerInterface{public function id():string{return'ok';}public function execute(array$c):array{return['ok'=>1];}public function compensate(array$c,array$r):void{}});$run=new WorkflowRun('r','wf',1,'site',[]);$run->approve(2);$out=(new WorkflowEngine($repo,$reg))->run(new WorkflowDefinition('wf',[['id'=>'a','action'=>'ok'],['id'=>'b','action'=>'ok']]),$run,'worker',1);$this->assertSame('completed',$out->status());$this->assertSame(2,$out->cursor());}
 public function test_failure_compensates_completed_steps():void{$repo=$this->repo();$reg=new ActionRegistry();$counter=(object)['compensated'=>0];$reg->register(new class($counter) implements ActionHandlerInterface{public function __construct(private object$c){}public function id():string{return'ok';}public function execute(array$x):array{return['x'=>1];}public function compensate(array$x,array$r):void{$this->c->compensated++;}});$reg->register(new class implements ActionHandlerInterface{public function id():string{return'fail';}public function execute(array$c):array{throw new RuntimeException('boom');}public function compensate(array$c,array$r):void{}});$run=new WorkflowRun('r2','wf',1,'site',[]);$run->approve(2);$out=(new WorkflowEngine($repo,$reg))->run(new WorkflowDefinition('wf',[['id'=>'a','action'=>'ok'],['id'=>'b','action'=>'fail']]),$run,'w',1);$this->assertSame('failed',$out->status());$this->assertSame(1,$counter->compensated);}
 public function test_secret_context_is_redacted():void{$r=new WorkflowRun('r','wf',1,'site',['password'=>'x','safe'=>'yes']);$this->assertArrayNotHasKey('password',$r->context());$this->assertSame('yes',$r->context()['safe']);}}
